import * as T from 'three';
import {localUp} from './planet.js';
export const SAS_MODES={maneuver:'予定噴射',hold:'姿勢保持',prograde:'順行',retrograde:'逆行',radial:'天頂',antiradial:'天底',normal:'軌道面＋',antinormal:'軌道面−'};
export function navDirections(pos,vel){const radial=localUp(pos),prograde=vel.length()>.5?vel.clone().normalize():null,normal=prograde?radial.clone().cross(prograde):null;if(normal&&normal.lengthSq()>1e-8)normal.normalize();else if(normal)normal.set(0,0,0);return {radial,antiradial:radial.clone().negate(),prograde,retrograde:prograde?.clone().negate(),normal:normal?.lengthSq()?normal:null,antinormal:normal?.lengthSq()?normal.clone().negate():null};}
export function attitudeTarget(q,forward,target){if(!target)return null;return new T.Quaternion().setFromUnitVectors(forward.clone().applyQuaternion(q).normalize(),target.clone().normalize()).multiply(q).normalize();}
export function navFrame(q,rocket){const forward=new T.Vector3(0,rocket?1:0,rocket?0:1).applyQuaternion(q),right=new T.Vector3(1,0,0).applyQuaternion(q),top=forward.clone().cross(right);return {forward,right,top};}
export function drawNavball(canvas,q,rocket,pos,vel){const ctx=canvas.getContext('2d'),w=canvas.width,c=w/2,r=c-4,{forward,right,top}=navFrame(q,rocket),directions=navDirections(pos,vel),up=directions.radial,ux=right.dot(up),uy=top.dot(up),uz=forward.dot(up),img=ctx.createImageData(w,w);for(let y=0;y<w;y++)for(let x=0;x<w;x++){const nx=(x-c)/r,ny=(c-y)/r,d=nx*nx+ny*ny;if(d>1)continue;const nz=Math.sqrt(1-d),h=nx*ux+ny*uy+nz*uz,elevation=Math.asin(T.MathUtils.clamp(h,-1,1)),line=Math.abs(h)<.018||Math.abs(Math.sin(elevation*6))<.035,sky=h>=0,color=line?[190,209,213]:sky?[37,96,133]:[136,78,43],shade=.55+.45*nz,i=(y*w+x)*4;img.data[i]=color[0]*shade;img.data[i+1]=color[1]*shade;img.data[i+2]=color[2]*shade;img.data[i+3]=255;}ctx.putImageData(img,0,0);for(const [name,color,label]of [['prograde','#b5f778','＋'],['retrograde','#b5f778','×'],['radial','#7de6ef','↑'],['antiradial','#7de6ef','↓'],['normal','#dba2ff','N'],['antinormal','#dba2ff','S']]){const v=directions[name];if(!v||v.dot(forward)<0)continue;const x=c+r*v.dot(right),y=c-r*v.dot(top);ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,y,7,0,Math.PI*2);ctx.stroke();ctx.font='bold 10px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(label,x,y);}ctx.strokeStyle='#ffbf68';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(c-25,c);ctx.lineTo(c-9,c);ctx.lineTo(c,c+5);ctx.lineTo(c+9,c);ctx.lineTo(c+25,c);ctx.stroke();ctx.strokeStyle='#8babb4';ctx.beginPath();ctx.arc(c,c,r,0,2*Math.PI);ctx.stroke();return {pitch:Math.asin(T.MathUtils.clamp(forward.dot(up),-1,1))*180/Math.PI};}
